ALTER TABLE "ClinicalOrder" ADD COLUMN "quotedUnitPrice" DECIMAL(14,2), ADD COLUMN "quotedPriceVersionId" UUID;
UPDATE "ClinicalOrder" o SET "quotedUnitPrice" = i."unitPrice", "quotedPriceVersionId" = i."priceVersionId" FROM (SELECT DISTINCT ON ("orderId") "orderId", "unitPrice", "priceVersionId" FROM "InvoiceItem" WHERE "orderId" IS NOT NULL ORDER BY "orderId", id) i WHERE i."orderId" = o.id;
UPDATE "ClinicalOrder" o SET "quotedUnitPrice" = COALESCE((SELECT v."unitPrice" FROM "CatalogPriceVersion" v WHERE v."catalogItemId" = c.id AND v."effectiveFrom" <= o."requestedAt" ORDER BY v."effectiveFrom" DESC LIMIT 1), c."unitPrice"), "quotedPriceVersionId" = (SELECT v.id FROM "CatalogPriceVersion" v WHERE v."catalogItemId" = c.id AND v."effectiveFrom" <= o."requestedAt" ORDER BY v."effectiveFrom" DESC LIMIT 1) FROM "Prescription" p JOIN "CatalogItem" c ON c.id = p."catalogItemId" WHERE p."orderId" = o.id AND o."quotedUnitPrice" IS NULL;
